INF102_Team_1-website\css\aispeler.css
	.extra-info > section.pixel-box {
		 flex:1 1 300px }
	figure {
		 flex:1 1 200px }
INF102_Team_1-website\css\conceptualthinking.css
	#diagram-galerij .pixel-box {
		 flex:1 1 800px }
INF102_Team_1-website\css\contact.css
	.naamkaart {
		 flex-wrap:nowrap }
	.feature-card {
		 flex:0 1 30rem }
INF102_Team_1-website\css\database.css
	.db-galerij .text-card {
		 flex:1 1 700px }
INF102_Team_1-website\css\erd.css
	.uitleg > article.pixel-box {
		 flex:1 1 400px }
INF102_Team_1-website\css\foto-galerij.css
	.themas > section.pixel-box {
		 flex:1 1 200px }
INF102_Team_1-website\css\gamemodel.css
	.model-info > section.pixel-box {
		 flex:1 1 340px }
	.spelverloop-lijst li {
		 display:flex,
		 flex-wrap:wrap }
	.spelverloop-lijst li::before {
		 flex-shrink:0 }
	.spelverloop-lijst p {
		 flex:1 1 300px }
	.spelverloop-lijst p.model-stap {
		 flex:0 1 290px }
	.statistieken > section.pixel-box {
		 flex:1 1 200px }
INF102_Team_1-website\css\general.css
	main,
		 header,
		 #menu .submenu:hover ul {
		 display:flex }
	header,
		 main {
		 flex-direction:column }
	#menu .submenu:hover ul {
		 flex-direction:column }
	.flex-container {
		 display:flex,
		 flex-direction:row,
		 flex-wrap:wrap }
	.flex-container > article.pixel-box {
		 flex:1 40% }
	.flex-column-container {
		 display:flex,
		 flex-direction:column }
	.chat-header {
		 flex-shrink:0 }
	.chat-body {
		 flex:1 1 auto }
	.chat-footer {
		 flex-shrink:0 }
	.chat-footer input {
		 flex:1 1 0 }
INF102_Team_1-website\css\index.css
	#hero nav {
		 flex-wrap:wrap,
		 flex-direction:row }
	.feature-card {
		 flex:1,
		 flex-direction:column }
	#features > section.pixel-box {
		 flex:1 1 150px }
	.marquee-track {
		 flex-wrap:nowrap }
INF102_Team_1-website\css\infrastructure.css
	.backup-stappen > section.infra-stap,
		 .https-stappen > section.infra-stap {
		 flex:1 1 220px }
INF102_Team_1-website\css\spelregels.css
	article > h2 {
		 flex:0 0 100% }
	article > section.pixel-box {
		 flex:0 0 100% }
	article > section.pixel-box:nth-child(4) {
		 flex-direction:row,
		 flex-wrap:wrap }
	article > section.pixel-box:nth-child(4) > h3,
		 article > section.pixel-box:nth-child(4) > p {
		 flex:0 0 100% }
	article > section.pixel-box:nth-child(4) > section.pixel-box {
		 flex:1 1 340px }
	article > section.pixel-box:nth-child(4) > section.pixel-box:last-child {
		 flex:0 0 100% }

INF102_Team_1-website\css\foto-galerij.css
	.foto-galerij-grid {
		 display:grid,
		 grid-template-columns:1fr 1fr }
INF102_Team_1-website\css\general.css
	#menu ul {
		 display:grid,
		 grid-auto-flow:column,
		 grid-auto-columns:1fr }
INF102_Team_1-website\css\multiplayer.css
	.sfeerbeelden-grid {
		 display:grid,
		 grid-template-columns:1fr 1fr }
